function loopEntry(next: number[]): number {
  let slow = 0, fast = 0;
  while (fast !== -1 && next[fast] !== -1) {
    slow = next[slow];
    fast = next[next[fast]];
    if (slow === fast) {
      let p = 0;
      while (p !== slow) {
        p = next[p];
        slow = next[slow];
      }
      return p;
    }
  }
  return -1;
}

